<?php if (!in_array($_SESSION['role'],['admin','pimpinan','aset'],true)){http_response_code(403);exit('Akses ditolak.');} ?><h1>Manajemen Aset</h1><?php if(in_array($_SESSION['role'],['admin','aset'],true)): ?><section class="card"><h2>Tambah Aset</h2><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><div class="formgrid"><label>Kode Aset<input name="kode" maxlength="60" required></label><label>Nama Aset<input name="nama" maxlength="180" required></label><label>Kategori<input name="kategori" maxlength="100"></label><label>Lokasi<input name="lokasi" maxlength="180"></label><label>Nilai Perolehan<input type="number" name="nilai" min="0" step=".01" value="0" required></label></div><button name="action" value="add_aset">Simpan</button></form></section><?php endif; ?><section class="card"><h2>Daftar Aset</h2><div class="tablewrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Kategori</th><th>Lokasi</th><th>Kondisi</th><th>Nilai</th></tr></thead><tbody><?php foreach(db()->query('SELECT kode,nama,kategori,lokasi,kondisi,nilai_perolehan FROM assets ORDER BY id DESC LIMIT 200') as $r): ?><tr><td><?=esc($r['kode'])?></td><td><?=esc($r['nama'])?></td><td><?=esc($r['kategori'])?></td><td><?=esc($r['lokasi'])?></td><td><?=esc($r['kondisi'])?></td><td><?=rupiah($r['nilai_perolehan'])?></td></tr><?php endforeach; ?></tbody></table></div></section>